SELECT pp.num_patients, pa.num_admissions, pp.avg_procedures_per_admission, pp.procedures_in_los_1_to_4_days::FLOAT / NULLIF(pp.num_admissions, 0) AS proportion_procedures_in_los_1_to_4_days, pp.procedures_in_los_5_to_7_days::FLOAT / NULLIF(pp.num_admissions, 0) AS proportion_procedures_in_los_5_to_7_days FROM (SELECT COUNT(DISTINCT subject_id) AS num_patients FROM male_patients) AS pp JOIN (SELECT COUNT(DISTINCT hadm_id) AS num_admissions FROM male_admissions) AS pa ON 1 = 1 LEFT JOIN procedures_per_admission pp ON pp.hadm_id = ma.hadm_id GROUP BY ma.hadm_id;